账面亏损_{i,t} = \sum_p abs(Close_{i,t} - Price_{i,p}) * Chip_{i,t,p} * I_{Close_{i,t} < Price_{i,p}}

CPLR_{i,t} = \frac{已实现亏损_{i,t}}{已实现亏损_{i,t} + 账面亏损_{i,t}}

CPGR_{i,t} = \frac{\text{已实现盈利}*{i,t}}{\text{已实现盈利}*{i,t} + \text{账面盈利}_{i,t}}

CPLR_{i,t} = \frac{\text{已实现亏损}*{i,t}}{\text{已实现亏损}*{i,t} + \text{账面亏损}_{i,t}}

VCDE1_{i,t} = abs(CPGR_{i,t} - CPLR_{i,t})

VCDE2_{i,t} = CPGR_{i,t} + 0.23 * CPLR_{i,t}

